Index: api/src/application/create-inscricao.ts
===================================================================
--- api/src/application/create-inscricao.ts	
+++ api/src/application/create-inscricao.ts	
@@ -1,64 +1,111 @@
 import crypto from 'node:crypto';
 import { DateTime } from 'luxon';
 import { ActivityRepository } from '../repositories/activity-repository.js';
 import { InscricaoRepository, InscricaoData } from '../repositories/inscricao-repository.js';
 import { Clock } from '../clock/clock.js';
 import { NotFoundError } from './errors.js';
-import { DomainError, sortEncontros } from '../domain/activity.js';
+import { DomainError, ConflictError, sortEncontros } from '../domain/activity.js';
 
+function hasEncounterOverlap(
+  encs1: Array<{ inicio: string; fim: string }>,
+  encs2: Array<{ inicio: string; fim: string }>
+): boolean {
+  for (const e1 of encs1) {
+    const start1 = DateTime.fromISO(e1.inicio, { setZone: true });
+    const end1 = DateTime.fromISO(e1.fim, { setZone: true });
+    for (const e2 of encs2) {
+      const start2 = DateTime.fromISO(e2.inicio, { setZone: true });
+      const end2 = DateTime.fromISO(e2.fim, { setZone: true });
+
+      if (start1 < end2 && end1 > start2) {
+        return true;
+      }
+    }
+  }
+  return false;
+}
+
 export class CreateInscricaoUseCase {
   constructor(
     private activityRepository: ActivityRepository,
     private inscricaoRepository: InscricaoRepository,
     private clock: Clock
   ) {}
 
   execute(atividadeId: string, participanteId: string): InscricaoData {
     const activity = this.activityRepository.findById(atividadeId);
     if (!activity) {
       throw new NotFoundError('Atividade não encontrada');
     }
 
     if (activity.cancelada === 1) {
       throw new DomainError('ATIVIDADE_CANCELADA', 'Atividade cancelada');
     }
 
     const agora = this.clock.now();
     const sortedEncontros = sortEncontros(activity.encontros);
     const primeiroInicio = DateTime.fromISO(sortedEncontros[0].inicio, { setZone: true });
     const limiteEncerramento = primeiroInicio.minus({ minutes: 30 });
 
     if (agora >= limiteEncerramento) {
       throw new DomainError('INSCRICOES_ENCERRADAS', 'Inscrições encerradas para esta atividade');
     }
 
+    // Check bloqueio por faltas (M5 / R4)
+    const endedActivities = this.inscricaoRepository.getEndedActivitiesForParticipant(participanteId);
+    let zeroPresencaCount = 0;
+    for (const endedAtv of endedActivities) {
+      const maxFim = DateTime.fromISO(endedAtv.maxFim, { setZone: true });
+      if (agora >= maxFim) {
+        if (!this.inscricaoRepository.hasPresencaInActivity(endedAtv.atividadeId, participanteId)) {
+          zeroPresencaCount++;
+        }
+      }
+    }
+    if (zeroPresencaCount >= 2) {
+      throw new DomainError('INSCRICAO_BLOQUEADA', 'Participante possui 2 ou mais atividades encerradas com zero presença');
+    }
+
     const existing = this.inscricaoRepository.findByActivityAndParticipant(atividadeId, participanteId);
     if (existing && ['confirmada', 'em_espera', 'convocada'].includes(existing.status)) {
       throw new DomainError('JA_INSCRITO', 'Participante já possui inscrição ativa nesta atividade');
     }
 
     const occupiedCount = this.inscricaoRepository.countOccupied(atividadeId);
     let status: 'confirmada' | 'em_espera' = 'confirmada';
     let posicaoNaEspera: number | null = null;
 
     if (occupiedCount >= activity.vagas) {
       status = 'em_espera';
       const waitlistCount = this.inscricaoRepository.countInWaitlist(atividadeId);
       posicaoNaEspera = waitlistCount + 1;
+    } else {
+      // Inscrição ocupará vaga -> Valida Conflito de Horários (R6) e Limite de Minicursos (R5)
+      const occupiedEncounters = this.inscricaoRepository.getOccupiedEncountersForParticipant(participanteId);
+      if (hasEncounterOverlap(activity.encontros, occupiedEncounters)) {
+        throw new ConflictError('CONFLITO_DE_HORARIO', 'Conflito de horário com outra atividade na qual o participante ocupa vaga');
+      }
+
+      if (activity.tipo === 'minicurso') {
+        const occupiedMinicursos = this.inscricaoRepository.countOccupiedMinicursos(participanteId);
+        if (occupiedMinicursos >= 3) {
+          throw new DomainError('LIMITE_DE_MINICURSOS', 'Participante já ocupa vaga em 3 minicursos');
+        }
+      }
     }
 
     const id = 'ins_' + crypto.randomBytes(4).toString('hex');
     const inscricao: InscricaoData = {
       id,
       atividadeId,
       participanteId,
       status,
       posicaoNaEspera,
       convocadaAte: null,
       criadaEm: agora.toISO() || new Date().toISOString()
     };
 
     this.inscricaoRepository.create(inscricao);
     return inscricao;
   }
 }

Index: api/src/repositories/inscricao-repository.ts
===================================================================
--- api/src/repositories/inscricao-repository.ts	
+++ api/src/repositories/inscricao-repository.ts	
@@ -1,108 +1,157 @@
 import Database from 'better-sqlite3';
 
 export interface InscricaoData {
   id: string;
   atividadeId: string;
   participanteId: string;
   status: 'confirmada' | 'em_espera' | 'convocada' | 'cancelada' | 'expirada';
   posicaoNaEspera: number | null;
   convocadaAte: string | null;
   criadaEm: string;
 }
 
 export class InscricaoRepository {
   constructor(private db: Database.Database) {}
 
   findStatus(atividadeId: string, participanteId: string): string | null {
     const row = this.db.prepare(`
       SELECT status FROM inscricoes
       WHERE atividadeId = ? AND participanteId = ?
     `).get(atividadeId, participanteId) as { status: string } | undefined;
 
     return row ? row.status : null;
   }
 
   findByActivityAndParticipant(atividadeId: string, participanteId: string): InscricaoData | null {
     const row = this.db.prepare(`
       SELECT id, atividadeId, participanteId, status, posicaoNaEspera, convocadaAte, criadaEm
       FROM inscricoes
       WHERE atividadeId = ? AND participanteId = ?
     `).get(atividadeId, participanteId) as InscricaoData | undefined;
 
     return row || null;
   }
 
   create(inscricao: InscricaoData): void {
     this.db.prepare(`
       INSERT INTO inscricoes (id, atividadeId, participanteId, status, posicaoNaEspera, convocadaAte, criadaEm)
       VALUES (?, ?, ?, ?, ?, ?, ?)
     `).run(
       inscricao.id,
       inscricao.atividadeId,
       inscricao.participanteId,
       inscricao.status,
       inscricao.posicaoNaEspera,
       inscricao.convocadaAte,
       inscricao.criadaEm
     );
   }
 
   countOccupied(atividadeId: string): number {
     const row = this.db.prepare(`
       SELECT COUNT(*) as count FROM inscricoes
       WHERE atividadeId = ? AND status IN ('confirmada', 'convocada')
     `).get(atividadeId) as { count: number };
     return row.count;
   }
 
   countInWaitlist(atividadeId: string): number {
     const row = this.db.prepare(`
       SELECT COUNT(*) as count FROM inscricoes
       WHERE atividadeId = ? AND status = 'em_espera'
     `).get(atividadeId) as { count: number };
     return row.count;
   }
 
+  countOccupiedMinicursos(participanteId: string): number {
+    const row = this.db.prepare(`
+      SELECT COUNT(DISTINCT i.atividadeId) as count
+      FROM inscricoes i
+      JOIN atividades a ON a.id = i.atividadeId
+      WHERE i.participanteId = ?
+        AND i.status IN ('confirmada', 'convocada')
+        AND a.tipo = 'minicurso'
+        AND a.cancelada = 0
+    `).get(participanteId) as { count: number };
+    return row.count;
+  }
+
+  getOccupiedEncountersForParticipant(participanteId: string): Array<{ inicio: string; fim: string }> {
+    return this.db.prepare(`
+      SELECT e.inicio, e.fim
+      FROM inscricoes i
+      JOIN encontros e ON e.atividade_id = i.atividadeId
+      JOIN atividades a ON a.id = i.atividadeId
+      WHERE i.participanteId = ?
+        AND i.status IN ('confirmada', 'convocada')
+        AND a.cancelada = 0
+    `).all(participanteId) as Array<{ inicio: string; fim: string }>;
+  }
+
   findByParticipant(participanteId: string, atividadeId?: string): InscricaoData[] {
     if (atividadeId) {
       return this.db.prepare(`
         SELECT id, atividadeId, participanteId, status, posicaoNaEspera, convocadaAte, criadaEm
         FROM inscricoes
         WHERE participanteId = ? AND atividadeId = ?
         ORDER BY criadaEm ASC
       `).all(participanteId, atividadeId) as InscricaoData[];
     }
     return this.db.prepare(`
       SELECT id, atividadeId, participanteId, status, posicaoNaEspera, convocadaAte, criadaEm
       FROM inscricoes
       WHERE participanteId = ?
       ORDER BY criadaEm ASC
     `).all(participanteId) as InscricaoData[];
   }
 
   findAll(atividadeId?: string): InscricaoData[] {
     if (atividadeId) {
       return this.db.prepare(`
         SELECT id, atividadeId, participanteId, status, posicaoNaEspera, convocadaAte, criadaEm
         FROM inscricoes
         WHERE atividadeId = ?
         ORDER BY criadaEm ASC
       `).all(atividadeId) as InscricaoData[];
     }
     return this.db.prepare(`
       SELECT id, atividadeId, participanteId, status, posicaoNaEspera, convocadaAte, criadaEm
       FROM inscricoes
       ORDER BY criadaEm ASC
     `).all() as InscricaoData[];
   }
 
   findById(id: string): InscricaoData | null {
     const row = this.db.prepare(`
       SELECT id, atividadeId, participanteId, status, posicaoNaEspera, convocadaAte, criadaEm
       FROM inscricoes
       WHERE id = ?
     `).get(id) as InscricaoData | undefined;
 
     return row || null;
   }
+
+  getEndedActivitiesForParticipant(participanteId: string): Array<{ atividadeId: string; maxFim: string }> {
+    return this.db.prepare(`
+      SELECT i.atividadeId, MAX(e.fim) as maxFim
+      FROM inscricoes i
+      JOIN encontros e ON e.atividade_id = i.atividadeId
+      JOIN atividades a ON a.id = i.atividadeId
+      WHERE i.participanteId = ?
+        AND i.status IN ('confirmada', 'convocada')
+        AND a.cancelada = 0
+      GROUP BY i.atividadeId
+    `).all(participanteId) as Array<{ atividadeId: string; maxFim: string }>;
+  }
+
+  hasPresencaInActivity(atividadeId: string, participanteId: string): boolean {
+    const row = this.db.prepare(`
+      SELECT p.id
+      FROM presencas p
+      JOIN encontros e ON e.id = p.encontroId
+      WHERE e.atividade_id = ? AND p.participanteId = ?
+      LIMIT 1
+    `).get(atividadeId, participanteId);
+    return !!row;
+  }
 }

Index: api/tests/inscricoes-fatia2.test.ts
===================================================================
--- api/tests/inscricoes-fatia2.test.ts	
+++ api/tests/inscricoes-fatia2.test.ts	
@@ -0,0 +1,444 @@
+import { describe, it, expect, beforeEach, afterEach } from 'vitest';
+import request from 'supertest';
+import path from 'path';
+import os from 'os';
+import fs from 'fs';
+import { createApp } from '../src/app.js';
+
+describe('M2 - Inscrições - Fatia 2 (Validações de Negócio e Conflitos)', () => {
+  let app: any;
+  let dbPath: string;
+
+  beforeEach(async () => {
+    const tmpDir = os.tmpdir();
+    dbPath = path.join(tmpDir, `test-inscricoes-f2-${Date.now()}-${Math.random()}.sqlite`);
+    app = createApp({ dbPath, modoTeste: true });
+    await request(app).post('/_teste/reset');
+  });
+
+  afterEach(() => {
+    app?.close?.();
+    if (fs.existsSync(dbPath)) {
+      try {
+        fs.unlinkSync(dbPath);
+      } catch {}
+    }
+  });
+
+  it('R4 (Critério 7) — recusa inscrição de participante bloqueado por faltas (2 atividades encerradas com zero presença em ambas) com 422 INSCRICAO_BLOQUEADA', async () => {
+    // 1. Relógio no passado (dia 19/10/2026 das 08:00 às 12:00)
+    await request(app)
+      .put('/_teste/relogio')
+      .send({ agora: '2026-10-19T08:00:00-03:00' });
+
+    // Cria Atividade 1 no passado
+    const atv1Res = await request(app)
+      .post('/atividades')
+      .set('X-Usuario', 'org-ana')
+      .send({
+        titulo: 'Atividade Faltosa 1',
+        tipo: 'palestra',
+        salaId: 'sala-101',
+        vagas: 20,
+        encontros: [
+          { inicio: '2026-10-19T09:00:00-03:00', fim: '2026-10-19T10:00:00-03:00' }
+        ]
+      });
+    const atv1Id = atv1Res.body.id;
+
+    // p-carla se inscreve na Atividade 1
+    await request(app)
+      .post(`/atividades/${atv1Id}/inscricoes`)
+      .set('X-Usuario', 'p-carla');
+
+    // Cria Atividade 2 no passado
+    const atv2Res = await request(app)
+      .post('/atividades')
+      .set('X-Usuario', 'org-ana')
+      .send({
+        titulo: 'Atividade Faltosa 2',
+        tipo: 'palestra',
+        salaId: 'sala-101',
+        vagas: 20,
+        encontros: [
+          { inicio: '2026-10-19T10:30:00-03:00', fim: '2026-10-19T11:30:00-03:00' }
+        ]
+      });
+    const atv2Id = atv2Res.body.id;
+
+    // p-carla se inscreve na Atividade 2
+    await request(app)
+      .post(`/atividades/${atv2Id}/inscricoes`)
+      .set('X-Usuario', 'p-carla');
+
+    // Avança relógio para depois do término das duas atividades (ex: 12:00:00)
+    await request(app)
+      .put('/_teste/relogio')
+      .send({ agora: '2026-10-19T12:00:00-03:00' });
+
+    // Cria Atividade 3 no futuro (ex: dia 20)
+    const atv3Res = await request(app)
+      .post('/atividades')
+      .set('X-Usuario', 'org-ana')
+      .send({
+        titulo: 'Atividade Futura',
+        tipo: 'palestra',
+        salaId: 'sala-101',
+        vagas: 20,
+        encontros: [
+          { inicio: '2026-10-20T10:00:00-03:00', fim: '2026-10-20T11:00:00-03:00' }
+        ]
+      });
+    const atv3Id = atv3Res.body.id;
+
+    // p-carla (que não registrou presença nem na Atividade 1 nem na 2) tenta se inscrever na Atividade 3
+    const res = await request(app)
+      .post(`/atividades/${atv3Id}/inscricoes`)
+      .set('X-Usuario', 'p-carla');
+
+    expect(res.status).toBe(422);
+    expect(res.body.erro).toBe('INSCRICAO_BLOQUEADA');
+    expect(typeof res.body.mensagem).toBe('string');
+  });
+
+  it('R5 (Critério 8) — recusa inscrição no 4º minicurso ocupando vaga com 422 LIMITE_DE_MINICURSOS', async () => {
+    // Cria 3 minicursos em dias/horários válidos (minicursos precisam de 2 a 5 encontros)
+    const mc1Res = await request(app).post('/atividades').set('X-Usuario', 'org-ana').send({
+      titulo: 'Minicurso 1', tipo: 'minicurso', salaId: 'sala-101', vagas: 10,
+      encontros: [
+        { inicio: '2026-10-20T08:00:00-03:00', fim: '2026-10-20T09:00:00-03:00' },
+        { inicio: '2026-10-20T09:30:00-03:00', fim: '2026-10-20T10:30:00-03:00' }
+      ]
+    });
+    expect(mc1Res.status).toBe(201);
+
+    const mc2Res = await request(app).post('/atividades').set('X-Usuario', 'org-ana').send({
+      titulo: 'Minicurso 2', tipo: 'minicurso', salaId: 'sala-101', vagas: 10,
+      encontros: [
+        { inicio: '2026-10-21T08:00:00-03:00', fim: '2026-10-21T09:00:00-03:00' },
+        { inicio: '2026-10-21T09:30:00-03:00', fim: '2026-10-21T10:30:00-03:00' }
+      ]
+    });
+    expect(mc2Res.status).toBe(201);
+
+    const mc3Res = await request(app).post('/atividades').set('X-Usuario', 'org-ana').send({
+      titulo: 'Minicurso 3', tipo: 'minicurso', salaId: 'sala-101', vagas: 10,
+      encontros: [
+        { inicio: '2026-10-22T08:00:00-03:00', fim: '2026-10-22T09:00:00-03:00' },
+        { inicio: '2026-10-22T09:30:00-03:00', fim: '2026-10-22T10:30:00-03:00' }
+      ]
+    });
+    expect(mc3Res.status).toBe(201);
+
+    // p-carla se inscreve nos 3 minicursos
+    await request(app).post(`/atividades/${mc1Res.body.id}/inscricoes`).set('X-Usuario', 'p-carla');
+    await request(app).post(`/atividades/${mc2Res.body.id}/inscricoes`).set('X-Usuario', 'p-carla');
+    await request(app).post(`/atividades/${mc3Res.body.id}/inscricoes`).set('X-Usuario', 'p-carla');
+
+    // Cria 4º minicurso
+    const mc4Res = await request(app).post('/atividades').set('X-Usuario', 'org-ana').send({
+      titulo: 'Minicurso 4', tipo: 'minicurso', salaId: 'sala-101', vagas: 10,
+      encontros: [
+        { inicio: '2026-10-23T08:00:00-03:00', fim: '2026-10-23T09:00:00-03:00' },
+        { inicio: '2026-10-23T09:30:00-03:00', fim: '2026-10-23T10:30:00-03:00' }
+      ]
+    });
+    expect(mc4Res.status).toBe(201);
+
+    // p-carla tenta se inscrever no 4º minicurso -> 422 LIMITE_DE_MINICURSOS
+    const res = await request(app)
+      .post(`/atividades/${mc4Res.body.id}/inscricoes`)
+      .set('X-Usuario', 'p-carla');
+
+    expect(res.status).toBe(422);
+    expect(res.body.erro).toBe('LIMITE_DE_MINICURSOS');
+    expect(typeof res.body.mensagem).toBe('string');
+  });
+
+  it('R5 (Critério 9) — permite inscrição quando participante tem 3 minicursos em estado em_espera', async () => {
+    // Cria 3 minicursos com apenas 1 vaga cada
+    const mc1Res = await request(app).post('/atividades').set('X-Usuario', 'org-ana').send({
+      titulo: 'Minicurso Wait 1', tipo: 'minicurso', salaId: 'sala-101', vagas: 1,
+      encontros: [
+        { inicio: '2026-10-20T08:00:00-03:00', fim: '2026-10-20T09:00:00-03:00' },
+        { inicio: '2026-10-20T09:30:00-03:00', fim: '2026-10-20T10:30:00-03:00' }
+      ]
+    });
+    const mc2Res = await request(app).post('/atividades').set('X-Usuario', 'org-ana').send({
+      titulo: 'Minicurso Wait 2', tipo: 'minicurso', salaId: 'sala-101', vagas: 1,
+      encontros: [
+        { inicio: '2026-10-21T08:00:00-03:00', fim: '2026-10-21T09:00:00-03:00' },
+        { inicio: '2026-10-21T09:30:00-03:00', fim: '2026-10-21T10:30:00-03:00' }
+      ]
+    });
+    const mc3Res = await request(app).post('/atividades').set('X-Usuario', 'org-ana').send({
+      titulo: 'Minicurso Wait 3', tipo: 'minicurso', salaId: 'sala-101', vagas: 1,
+      encontros: [
+        { inicio: '2026-10-22T08:00:00-03:00', fim: '2026-10-22T09:00:00-03:00' },
+        { inicio: '2026-10-22T09:30:00-03:00', fim: '2026-10-22T10:30:00-03:00' }
+      ]
+    });
+
+    // p-diego ocupa as únicas vagas
+    await request(app).post(`/atividades/${mc1Res.body.id}/inscricoes`).set('X-Usuario', 'p-diego');
+    await request(app).post(`/atividades/${mc2Res.body.id}/inscricoes`).set('X-Usuario', 'p-diego');
+    await request(app).post(`/atividades/${mc3Res.body.id}/inscricoes`).set('X-Usuario', 'p-diego');
+
+    // p-carla entra em lista de espera nos 3 minicursos
+    const ins1 = await request(app).post(`/atividades/${mc1Res.body.id}/inscricoes`).set('X-Usuario', 'p-carla');
+    const ins2 = await request(app).post(`/atividades/${mc2Res.body.id}/inscricoes`).set('X-Usuario', 'p-carla');
+    const ins3 = await request(app).post(`/atividades/${mc3Res.body.id}/inscricoes`).set('X-Usuario', 'p-carla');
+
+    expect(ins1.body.status).toBe('em_espera');
+    expect(ins2.body.status).toBe('em_espera');
+    expect(ins3.body.status).toBe('em_espera');
+
+    // Cria 4º minicurso com vagas
+    const mc4Res = await request(app).post('/atividades').set('X-Usuario', 'org-ana').send({
+      titulo: 'Minicurso Wait 4', tipo: 'minicurso', salaId: 'sala-101', vagas: 10,
+      encontros: [
+        { inicio: '2026-10-23T08:00:00-03:00', fim: '2026-10-23T09:00:00-03:00' },
+        { inicio: '2026-10-23T09:30:00-03:00', fim: '2026-10-23T10:30:00-03:00' }
+      ]
+    });
+
+    // p-carla tenta se inscrever no 4º minicurso -> Aceita com 201 confirmada
+    const res = await request(app)
+      .post(`/atividades/${mc4Res.body.id}/inscricoes`)
+      .set('X-Usuario', 'p-carla');
+
+    expect(res.status).toBe(201);
+    expect(res.body.status).toBe('confirmada');
+  });
+
+  it('R5 (Critério 10) — permite inscrição em minicurso quando participante tem 3 palestras confirmadas', async () => {
+    // Cria 3 palestras
+    const p1Res = await request(app).post('/atividades').set('X-Usuario', 'org-ana').send({
+      titulo: 'Palestra 1', tipo: 'palestra', salaId: 'sala-101', vagas: 10,
